mapper.select:
SELECT

FROM t_message
WHERE deleted = 0
  AND receiver_id = #{receiverId}

    AND is_read = #{query.read}


    AND message_type = #{query.messageType}


    AND level = #{query.level}

ORDER BY is_read ASC, create_time DESC

mapper.update:
UPDATE t_message
SET is_read = 1,
    read_at = NOW()
WHERE id = #{messageId}
  AND receiver_id = #{receiverId}
  AND deleted = 0

UPDATE t_message
SET deleted = #{deletedAt}
WHERE id = #{id}
  AND receiver_id = #{receiverId}
  AND deleted = 0

UPDATE t_message
SET deleted = #{deletedAt}
WHERE is_read = 1
  AND deleted = 0
  AND create_time < #{cutoff}

